\u0057\u0077\u006c\u006c\u003c\u004e\u0050\u0067\u005f\u007e\u0024\u007d\u0077\u0068\u004d\u0058\u006d\u0053\u0050\u007a\u0033\u004b\u0059\u0060\u006c\u0030\u0072\u003f\u002e\u0039\u0063\u0059\u003d\u004e\u0056\u006d\u006f\u007a\u0057\u0077\u006c\u006c\u003c\u004e\u0050\u0067\u005f\u007e\u0024\u007d\u0077\u0068\u004d\u0058\u006d\u0053\u0050\u005f\u0037\u0068\u003a\u0037\u003a\u002b\u0047\u0077\u004a\u0059\u004c\u007c\u003f\u0026\u0032\u0053\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u0066\u0059\u004a\u0034\u0060\u0072\u004b\u003d\u0069\u003d\u0071\u0035\u0058\u0045\u0056\u006e\u003b\u0040\u0023\u002f\u0044\u0048\u0074\u006e\u0052\u0024\u004b\u004e\u005a\u005d\u002a\u0051\u0058\u006d\u0059\u0023\u0034\u0077\u0079\u0063\u005f\u0058\u0026\u0070\u003f\u002e\u0066\u005f\u0044\u004f\u0033\u0037\u004a\u006e\u003b\u0040\u0077\u0068\u0065\u0026\u0024\u006d\u002c\u005e\u0068\u0029\u0025\u0025\u004a\u0078\u005f\u0071\u0034\u0028\u0036\u0063\u003a\u0030\u0067\u003a\u002c\u0026\u0024\u006d\u0046\u005d\u004b\u0021\u0024\u006d\u0046\u005d\u0059\u002c\u003d\u0078\u004c\u007d\u003a\u003e\u004d\u0077\u0028\u006f\u007b\u0068\u007b\u003a\u004b\u003c\u002a\u003d\u0053\u005f\u004b\u004e\u0028\u0050\u0078\u0038\u0066\u003f\u002a\u0039\u002c\u0029\u005b\u002e\u0030\u003f\u0055\u003f\u0062\u0037\u0044\u003c\u0072\u0040\u0043\u005d\u0072\u0076\u0053\u005f\u0040\u003f\u0039\u003d\u0028\u0050\u0073\u007c\u0061\u0078\u005d\u0079\u0026\u0028\u003b\u0030\u003d\u007d\u0078\u003d\u0075\u002f\u0070\u005b\u004a\u0070\u0070\u005e\u007c\u0058\u0025\u0025\u0030\u003f\u0044\u0035\u003e\u006e\u0029\u007c\u0054\u0050\u0043\u005d\u007a\u0021\u0044\u002b\u004a\u004c\u005e\u0043\u0040\u0045\u0038\u006f\u005d\u0072\u002e\u005d\u006e\u007a\u003f\u0072\u006b\u0034\u0054\u0069\u0044\u002b\u004a\u004c\u002b\u0041\u0032\u0062\u004f\u0026\u004f\u0040\u0066\u0034\u0021\u0064\u0026\u0030\u0058\u0039\u0048\u0029\u0045\u0038\u0046\u0051\u004a\u0070\u0046\u005d\u004b\u0079\u0071\u0048\u004c\u005f\u005e\u0043\u0040\u0045\u0038\u006f\u0071\u0050\u007d\u0043\u0065\u0029\u007a\u003d\u0052\u0024\u002e\u0023\u0058\u0045\u004b\u0077\u0045\u003a\u0060\u0043\u0078\u007e\u0063\u0041\u003e\u003f\u0026\u0036\u002c\u0032\u0059\u006e\u002a\u0050\u005f\u0076\u005b\u0021\u0044\u002b\u004a\u004c\u003b\u0022\u0076\u007b\u004b\u006b\u004d\u006f\u0040\u002f\u0067\u004f\u003b\u0041\u005f\u004c\u0075\u0046\u004b\u0028\u006b\u0063\u0074\u0065\u0070\u005e\u0068\u0029\u0026\u0030\u0051\u003f\u0042\u0056\u0045\u006a\u003f\u0038\u0033\u006f\u002c\u0068\u0059\u0029\u006b\u0054\u0025\u003f\u0056\u0042\u007d\u0041\u0072\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u005d\u0055\u002f\u0034\u006a\u0076\u002a\u004a\u0059\u004c\u005d\u0029\u007b\u002f\u0074\u007c\u0049\u0057\u002a\u0039\u004e\u0029\u006e\u0026\u006a\u003f\u0076\u0030\u0026\u0071\u005f\u0044\u0074\u006d\u0026\u0071\u005f\u0044\u0074\u006d\u0026\u0071\u005f\u0044\u0074\u006d\u0051\u0048\u007b\u003f\u007a\u004e\u0022\u002f\u0036\u0029\u0044\u002b\u004a\u004c\u0023\u0035\u005e\u002f\u0060\u006e\u002c\u0053\u004d\u0043\u003d\u004e\u006f\u0046\u006a\u0024\u0046\u0069\u0046\u0040\u0063\u007d\u0023\u0028\u006f\u006d\u004a\u004c\u003f\u0069\u0025\u0025\u004a\u0078\u005f\u0071\u0034\u0028\u0036\u0063\u0059\u0036\u0035\u0032\u0078\u0031\u002f\u0023\u0040\u004c\u003f\u0069\u0026\u0030\u003d\u007d\u006f\u0044\u004c\u002f\u003e\u004b\u006a\u0055\u0069\u0034\u0059\u0029\u002f\u0050\u0041\u0055\u0029\u0047\u0038\u003b\u007b\u0029\u007b\u002f\u005d\u003f\u003d\u002b\u0025\u005a\u003e\u0037\u0041\u004a\u0051\u003f\u0063\u0029\u007c\u0042\u0028\u0062\u0074\u006d\u005a\u0041\u0070\u0051\u0053\u0031\u0056\u006a\u003a\u0026\u0024\u006d\u0046\u005d\u004b\u0021\u0024\u006d\u002c\u005e\u0047\u0065\u0058\u003d\u004a\u0078\u004b\u004e\u0062\u0037\u0062\u004d\u0058\u006d\u0053\u0050\u005f\u0037\u0068\u003a\u0037\u003a\u002b\u0047\u0077\u004a\u0059\u004c\u007c\u003f\u0026\u0032\u0053\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u0066\u0059\u004a\u0034\u0060\u0072\u004b\u003d\u0069\u003d\u0071\u0035\u0058\u0045\u0056\u006e\u003b\u0040\u0023\u002f\u0026\u006e\u0068\u0025\u0055\u003f\u006c\u0044\u0054\u0033\u0038\u006f\u004b\u0059\u0053\u0068\u006a\u0026\u0024\u006d\u002c\u005e\u0068\u0029\u0023\u0048\u0036\u0044\u0047\u0024\u0029\u0071\u0031\u006f\u0062\u0053\u0071\u0034\u0059\u0029\u0065\u0046\u004f\u005f\u0033\u003d\u0076\u0028\u0068\u004d\u0058\u006d\u0053\u0050\u004b\u0077\u0078\u0075\u0039\u0079\u0023\u0043\u0029\u0040\u003d\u007d\u0048\u0070\u004a\u0056\u0032\u0063\u0043\u0029\u0067\u003a\u002c\u0026\u0024\u006d\u0046\u005d\u004b\u0021\u0024\u006d\u002c\u005e\u0022\u003c\u0072\u0048\u0054\u005f\u002f\u002b\u0077\u007e\u002a\u0051\u0058\u006d\u0033\u0037\u0059\u0038\u0037\u0055\u002f\u0034\u0059\u0029\u005e\u0057\u006d\u0022\u0058\u002c\u005a\u0041\u0070\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u0072\u0055\u0044\u003a\u0052\u0079\u0060\u0025\u0041\u0035\u0030\u004f\u0059\u0023\u006a\u003f\u0035\u0047\u0063\u002f\u0036\u0029\u0044\u002b\u004a\u004c\u005b\u0035\u0058\u0045\u0074\u0033\u004b\u0059\u0048\u0079\u0053\u0065\u0065\u004a\u0059\u004c\u0065\u0029\u004b\u006e\u0068\u004d\u0058\u006d\u0053\u0050\u0041\u0077\u0067\u0040\u0073\u0043\u007c\u0037\u004b\u0078\u0048\u007d\u003e\u0045\u0023\u006a\u007a\u006b\u0023\u002b\u0072\u0032\u0078\u0031\u002f\u0023\u0040\u004c\u003f\u0069\u005f\u003e\u002e\u0078\u007b\u0070\u0069\u0042\u0029\u007c\u0064\u007c\u0071\u0034\u002e\u0067\u0071\u002e\u0048\u0034\u007d\u002c\u007c\u0045\u0033\u006e\u0078\u003a\u0054\u006c\u002e\u0076\u002f\u0023\u0040\u004c\u0052\u006f\u003b\u0029\u002a\u0051\u0035\u0031\u0051\u0034\u005e\u0047\u003f\u002e\u006a\u0024\u004b\u004c\u006b\u0045\u0053\u0051\u0074\u0072\u0070\u005e\u0068\u0029\u0025\u007c\u004d\u0044\u0062\u0070\u0068\u006a\u0046\u0051\u0068\u002b\u0068\u0067\u0078\u0021\u0044\u002b\u004a\u004c\u0038\u0051\u005f\u0033\u0067\u006b\u006b\u0040\u0023\u002f\u0054\u0077\u003b\u0041\u0026\u0034\u0054\u0069\u0044\u002b\u004a\u004c\u006f\u0042\u0030\u0077\u0067\u006b\u0064\u0055\u0072\u0034\u0051\u004e\u004b\u0078\u003d\u007d\u0078\u0035\u0036\u007e\u0046\u0051\u006b\u0069\u0051\u0048\u002b\u006b\u0051\u003e\u0044\u002f\u0036\u0029\u0044\u002b\u004a\u004c\u0023\u0035\u005e\u002f\u0060\u006e\u002c\u0053\u004d\u0043\u003d\u004e\u006f\u0046\u006a\u0024\u0046\u0069\u0059\u0050\u004d\u0075\u006e\u0060\u004f\u0050\u006a\u0051\u0049\u004c\u007b\u003a\u0049\u0079\u005e\u005e\u0030\u003f\u004a\u0035\u003e\u007e\u0046\u0051\u005e\u002b\u0066\u0032\u0054\u0077\u003b\u0041\u005f\u004c\u0022\u0029\u0051\u0048\u002b\u006b\u0051\u003e\u0044\u002f\u0036\u0029\u002e\u0070\u006c\u0042\u0054\u0069\u003d\u0078\u002c\u0063\u0054\u002b\u0077\u007e\u002a\u0051\u0058\u006d\u0033\u0037\u003d\u004f\u0058\u0040\u0062\u0039\u0059\u0029\u0021\u0050\u0055\u0025\u0062\u0077\u006f\u006d\u004a\u004c\u003f\u0069\u0077\u0046\u005e\u0044\u0072\u0030\u0051\u007e\u0046\u0051\u0040\u0059\u0073\u0043\u006a\u0026\u0024\u006d\u002c\u005e\u0068\u0029\u002c\u003d\u007b\u0024\u0069\u003f\u0036\u0033\u004c\u0063\u0049\u004c\u0036\u0058\u0077\u0048\u0035\u005f\u006a\u0042\u003f\u0069\u0044\u002b\u003f\u005f\u0058\u004e\u006a\u0033\u002c\u0028\u0023\u002b\u0066\u0032\u006a\u003e\u003d\u005d\u0068\u007d\u006e\u0060\u004f\u0050\u006a\u0051\u0049\u004c\u007b\u003a\u0040\u004e\u0049\u0071\u0061\u003d\u0036\u0041\u0059\u0033\u0076\u0064\u006b\u0072\u0046\u005e\u004f\u007a\u0041\u007d\u006a\u0042\u003f\u0069\u0044\u002b\u0038\u003f\u003b\u004e\u0046\u0028\u0035\u007c\u0023\u002b\u0067\u0058\u0023\u0072\u0038\u0048\u002e\u0078\u003a\u0028\u006f\u006d\u004a\u004c\u003e\u005b\u007c\u006d\u004a\u004c\u003a\u0043\u006c\u0033\u0031\u006f\u0062\u0053\u0028\u0079\u0067\u007c\u0025\u0078\u006c\u0042\u003f\u0069\u0044\u002b\u0026\u0078\u0026\u003f\u0048\u006a\u0046\u0051\u0053\u0075\u0036\u003a\u0063\u0048\u005a\u005e\u0036\u0044\u0033\u003d\u0071\u004e\u002a\u004b\u0077\u0076\u0022\u002f\u0036\u0029\u0044\u002b\u004a\u004c\u002a\u0070\u0076\u0028\u005d\u0053\u0073\u0072\u002e\u005d\u005d\u0028\u0068\u006f\u004f\u0034\u0054\u0069\u0044\u002b\u004a\u004c\u002a\u0070\u0076\u0028\u005d\u0053\u0062\u0053\u0049\u0043\u003a\u004e\u002f\u005e\u0048\u0034\u0062\u0029\u004e\u0071\u0072\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u003c\u0075\u0054\u0068\u0033\u006b\u0072\u0048\u004d\u0044\u007e\u0024\u0054\u005e\u0053\u006e\u0053\u0057\u005e\u003a\u0079\u007a\u0050\u0050\u0057\u003a\u0040\u002b\u0022\u0033\u0075\u006f\u002f\u0058\u006b\u002b\u0068\u0029\u006d\u0060\u0040\u004c\u007a\u007d\u0035\u002f\u0054\u004f\u006c\u0059\u0069\u0076\u0070\u0076\u0077\u004a\u0068\u003f\u0056\u0070\u0023\u006a\u0056\u006e\u0074\u006d\u0076\u006e\u0066\u003c\u004f\u0040\u0028\u006c\u0067\u0046\u0058\u003d\u0033\u0025\u003e\u0045\u007a\u0056\u0023\u0026\u0034\u0050\u002c\u005a\u0036\u0029\u0044\u002b\u004a\u004c\u0024\u0071\u002a\u0045\u0032\u0063\u007b\u0068\u007e\u0068\u0068\u004e\u002f\u0023\u0040\u004c\u0052\u006f\u003b\u0029\u002a\u0051\u0035\u0031\u0030\u0068\u002b\u0047\u004c\u005f\u0074\u003d\u0051\u003d\u002e\u002f\u006a\u0055\u0034\u006d\u0053\u0050\u006a\u0051\u007c\u0076\u005e\u003a\u0025\u0064\u002e\u0070\u0051\u0024\u0079\u0030\u0045\u002a\u0034\u0077\u002b\u003a\u006f\u0079\u0043\u0037\u0071\u0048\u005d\u0021\u006e\u0060\u004f\u0050\u006a\u0051\u007b\u0068\u0035\u0034\u007a\u0067\u0061\u0046\u002a\u0034\u006b\u0032\u005a\u0041\u006f\u0062\u004e\u0070\u0070\u005e\u0068\u0029\u003d\u0078\u0055\u0024\u0063\u0035\u0055\u0033\u003b\u0033\u0030\u007b\u002c\u0068\u0064\u0065\u004e\u0050\u003b\u0025\u007b\u002c\u003a\u005d\u002a\u0051\u0058\u006d\u0053\u0050\u0029\u007c\u0064\u007c\u004a\u0043\u0043\u003c\u0022\u0026\u0053\u005f\u0046\u0069\u007a\u003d\u004c\u005f\u0068\u002b\u0051\u0048\u007c\u0062\u002f\u0039\u0043\u005d\u0074\u003e\u0059\u002e\u007c\u0034\u0054\u0069\u0044\u002b\u0041\u004c\u0025\u003e\u005b\u004f\u0050\u0024\u0056\u002e\u0057\u0054\u006c\u0050\u002e\u004b\u0078\u0046\u0078\u0035\u004f\u005e\u0077\u0028\u006f\u0036\u0022\u0077\u0068\u0030\u0029\u002a\u0040\u002f\u005f\u003e\u0045\u0055\u0033\u003f\u0053\u0038\u0076\u0025\u007b\u0057\u0048\u0062\u0025\u0072\u0063\u002f\u002b\u0077\u007e\u002a\u0051\u0058\u006d\u0077\u0047\u004c\u004f\u006f\u0057\u0040\u002f\u0044\u0048\u004a\u0047\u0056\u0039\u006e\u0060\u004f\u0050\u006d\u0074\u0073\u0065\u0070\u005e\u007c\u0058\u004c\u0026\u0053\u005f\u0026\u004e\u006b\u0045\u0025\u006f\u006a\u006c\u0077\u002b\u0068\u0029\u0044\u002b\u003a\u0078\u007e\u006a\u007c\u0045\u0047\u004b\u003b\u0072\u0046\u005e\u0063\u006c\u0063\u0041\u0026\u0034\u0054\u0069\u0044\u002b\u004a\u004c\u0051\u0046\u0075\u002f\u003d\u004f\u007c\u0076\u006d\u007b\u002c\u0067\u0038\u0048\u002e\u0078\u0035\u0070\u0054\u005e\u0074\u007c\u0032\u0032\u0073\u006c\u0028\u0079\u0076\u0046\u003b\u0024\u003f\u003d\u003b\u007b\u006b\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u006f\u004d\u0057\u003a\u0059\u0029\u0071\u0050\u0056\u0066\u006e\u0060\u004f\u0050\u006a\u0051\u0028\u003c\u004c\u0068\u0073\u007e\u0075\u006b\u0074\u003d\u0035\u0035\u006f\u006a\u0046\u0051\u005a\u002b\u0068\u0067\u0078\u0021\u0044\u002b\u006d\u0073\u0051\u0060\u004f\u0050\u0024\u0056\u0076\u0055\u0044\u003a\u0074\u0037\u0064\u0048\u007b\u0024\u0061\u005e\u005b\u002f\u0064\u006f\u003a\u006f\u0058\u005d\u007a\u0021\u0044\u002b\u004a\u004c\u005a\u0068\u0042\u0056\u002e\u003b\u0023\u002b\u002c\u007b\u0078\u0021\u0044\u002b\u004a\u004c\u0061\u005e\u004d\u0077\u0047\u0053\u0047\u0075\u007e\u0058\u0033\u0043\u0026\u0071\u0059\u004c\u0055\u0034\u0021\u0033\u0022\u0060\u005a\u005b\u0056\u0045\u0030\u0029\u0066\u0072\u0058\u0039\u003e\u0069\u0066\u0072\u0058\u0039\u003e\u0069\u0070\u0057\u0052\u0025\u0052\u0023\u003a\u005d\u002a\u0051\u0058\u006d\u0077\u0047\u0059\u0038\u002b\u0023\u0053\u0068\u003a\u0064\u0046\u0054\u0063\u007d\u005b\u002b\u0072\u0028\u0030\u0077\u004f\u0040\u0079\u005e\u0073\u007e\u0076\u003d\u0039\u0021\u0070\u002c\u002e\u0041\u0070\u0051\u005a\u005b\u0056\u0045\u0030\u0029\u0066\u0072\u0058\u0039\u003e\u0069\u0070\u0057\u0071\u0068\u0044\u0077\u006f\u006d\u004a\u004c\u003f\u0069\u0025\u0025\u004a\u0078\u005f\u0071\u0034\u0028\u0036\u0063\u0077\u0060\u0067\u003a\u002e\u0029\u0031\u0078\u006a\u0042\u003f\u0069\u0044\u002b\u003e\u003f\u0038\u004e\u0059\u0033\u0063\u007c\u0051\u0054\u0054\u0068\u0034\u0072\u0026\u005f\u005d\u0034\u0065\u0065\u0038\u0045\u0053\u0063\u0034\u006d\u0053\u0050\u006a\u0051\u0076\u0055\u0036\u0058\u0052\u0037\u004e\u0050\u0056\u0054\u002a\u0045\u0030\u0077\u0068\u004d\u0058\u006d\u0053\u0050\u0043\u0057\u0053\u0075\u0060\u0043\u0052\u0037\u004e\u0050\u007d\u007d\u0048\u0071\u0058\u0045\u0056\u006e\u0022\u0058\u006b\u002b\u0068\u0029\u0044\u002b\u0026\u0078\u007e\u0024\u007a\u0056\u006d\u006f\u0076\u0072\u0077\u0068\u0059\u0029\u003e\u0050\u0056\u0066\u006e\u0060\u004f\u0050\u006a\u0051\u0066\u003f\u007b\u003a\u004b\u003c\u0057\u007c\u002e\u0078\u0028\u0034\u0025\u0045\u002f\u0063\u0066\u003f\u0035\u0032\u0030\u0026\u0024\u006d\u0046\u005d\u004b\u0021\u0024\u006d\u002c\u005e\u0073\u0048\u0044\u006b\u0052\u0024\u0063\u0035\u0041\u0028\u004f\u0051\u0071\u0059\u0035\u0034\u004b\u0067\u0062\u006b\u003d\u003f\u0056\u0070\u0023\u006a\u0056\u006e\u0031\u0068\u007e\u0058\u0033\u0043\u0044\u0041\u004a\u0035\u0054\u0069\u0044\u002b\u004a\u004c\u006f\u0042\u0030\u0077\u0067\u006b\u0064\u0055\u0072\u0034\u0051\u004e\u004e\u0050\u0056\u0054\u006d\u0039\u005d\u004a\u0064\u0062\u0055\u006c\u006b\u002b\u0068\u0029\u0044\u002b\u0038\u003f\u0061\u003f\u003c\u006a\u0045\u0063\u007b\u0068\u0049\u0068\u002b\u006a\u002f\u0023\u0040\u004c\u003f\u0069\u0026\u0030\u003d\u007d\u003e\u0054\u003b\u007b\u0049\u0033\u0076\u0055\u0036\u0058\u0052\u0037\u004e\u0050\u0056\u0054\u006d\u0039\u005d\u004a\u0064\u0062\u0055\u006c\u006b\u002b\u0068\u0029\u006d\u0060\u002f\u005a\u0074\u007b\u007a\u0056\u0071\u0077\u0069\u007c\u006b\u002b\u0024\u0067\u0077\u0046\u0051\u003f\u0029\u0052\u0026\u0069\u0048\u003f\u0035\u0054\u006c\u007e\u0039\u004d\u007a\u007a\u0070\u006c\u002a\u0077\u0025\u0078\u002f\u005f\u0047\u006a\u002c\u0056\u004d\u0040\u0045\u007b\u004c\u0068\u0043\u0067\u0057\u007c\u0051\u0024\u004d\u003e\u0042\u002a\u0039\u004d\u0058\u006d\u0071\u005e\u004c\u004f\u006a\u0050\u007d\u0068\u002b\u0047\u0053\u005f\u007e\u005a\u007c\u0051\u005f\u0033\u006a\u0037\u0035\u0075\u005e\u0036\u0044\u0021\u0044\u002b\u004a\u004c\u004c\u0031\u0060\u0033\u0023\u0026\u007b\u0068\u0036\u0058\u0040\u006b\u0059\u002e\u0042\u0054\u006a\u0071\u005a\u002f\u0059\u006e\u0047\u0031\u0070\u0021\u0068\u0053\u0046\u003d\u0025\u007d\u0062\u0029\u0057\u0033\u0070\u0028\u0049\u0057\u004a\u0032\u0034\u0072\u0043\u006b\u006a\u0042\u003f\u0069\u0044\u002b\u0075\u005a\u005f\u0071\u0044\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u0030\u0078\u0055\u0024\u0059\u0070\u0077\u0028\u0049\u0033\u006a\u0055\u0066\u0034\u0022\u0049\u0044\u006f\u0034\u0078\u0041\u0079\u0029\u005d\u002a\u0051\u0034\u004b\u004a\u0032\u0034\u0072\u0043\u006b\u006a\u0042\u003f\u0069\u0024\u006d\u002c\u005e\u0036\u006b\u0074\u0026\u0078\u004c\u0065\u0071\u007d\u0077\u007a\u003e\u0063\u0047\u003c\u002f\u0058\u007a\u0044\u002b\u005b\u004c\u0036\u004b\u007b\u0041\u005d\u003f\u003d\u002b\u002b\u0036\u0028\u0070\u002e\u0046\u0042\u0054\u005d\u0071\u0076\u007b\u0062\u0038\u007b\u0078\u0068\u0039\u0022\u0049\u0024\u006d\u002c\u005e\u0068\u0029\u002c\u0047\u002c\u0078\u0076\u006a\u0029\u005d\u002a\u0051\u0058\u006d\u0053\u0050\u006a\u0051\u0077\u004b\u002a\u0039\u002c\u0076\u006e\u0071\u004c\u0023\u0036\u0041\u0059\u0033\u005b\u006e\u003b\u0040\u0043\u005d\u003a\u004e\u0039\u0023\u006f\u0063\u0066\u0071\u007a\u0056\u003a\u005d\u0054\u0032\u002c\u0068\u0039\u0029\u002a\u0025\u0047\u005a\u0078\u0029\u0023\u002a\u006a\u0051\u0071\u0032\u0057\u002f\u0058\u007a\u0054\u0040\u004a\u004c\u0049\u004e\u0078\u005d\u0028\u0062\u0036\u0054\u0046\u005d\u0069\u0037\u0068\u0023\u0023\u0068\u0048\u0029\u0023\u002a\u0079\u0035\u0034\u006d\u0053\u0050\u006a\u0051\u0058\u006d\u0053\u0050\u0071\u0066\u0042\u0023\u006a\u003a\u0070\u0029\u0022\u006b\u006d\u0022\u0059\u003d\u007a\u0056\u004d\u0040\u0068\u005b\u006d\u0036\u0026\u006e\u007c\u0026\u002a\u007d\u0052\u0032\u006b\u0045\u0062\u0038\u002c\u0053\u0050\u004e\u0072\u007b\u002b\u006b\u0054\u006e\u002f\u003d\u0040\u0023\u006d\u0039\u002b\u006a\u0075\u0062\u0070\u0070\u0070\u005e\u0068\u0029\u0044\u002b\u004a\u004c\u003f\u0069\u0022\u0022\u0055\u0024\u005a\u003e\u0062\u0037\u0042\u006b\u004c\u003a\u0077\u0068\u0024\u0055\u0029\u002b\u0043\u0039\u0042\u0036\u0033\u0037\u006f\u006f\u0024\u0050\u006d\u007b\u002c\u0067\u002a\u0026\u005a\u0024\u004a\u0036\u006a\u0023\u007e\u0037\u0067\u0040\u0053\u0068\u003f\u002a\u007b\u0057\u006a\u0042\u003f\u0069\u0044\u002b\u004a\u004c\u003f\u0069\u005f\u003e\u0047\u0024\u0035\u0035\u007c\u0045\u0021\u0038\u006d\u0022\u004a\u0043\u0079\u003c\u0039\u0023\u0023\u0068\u0048\u0029\u0023\u002a\u006a\u0051\u0042\u0023\u006a\u003a\u0026\u0079\u004c\u0026\u004c\u005f\u0038\u004e\u0044\u005d\u0058\u0040\u0049\u0078\u0065\u0068\u0052\u005d\u006f\u0040\u0076\u0025\u004f\u0060\u004f\u0050\u006a\u0051\u0058\u006d\u0053\u0050\u0034\u0062\u002b\u007b\u005f\u0058\u0074\u003e\u006b\u0026\u0025\u0024\u005b\u0054\u0037\u0033\u0072\u0028\u005b\u006f\u006b\u002b\u0068\u0029\u0044\u002b\u004a\u004c\u004c\u0031\u002b\u0056\u002c\u0028\u0028\u004d\u004c\u0043\u0043\u0037\u0071\u0048\u005e\u0044\u0029\u0024\u005a\u002f\u0052\u003c\u0033\u0053\u002b\u0036\u007d\u006c\u0042\u005f\u0057\u0044\u005f\u004e\u004e\u0032\u0068\u0040\u0043\u0029\u0058\u007b\u0021\u002a\u003f\u0072\u006d\u0054\u006c\u0037\u0028\u0071\u004d\u0040\u0068\u005b\u006d\u0036\u0055\u0038\u0035\u0072\u0042\u0054\u006a\u0021\u006d\u0042\u0068\u0052\u0051\u004f\u0050\u004e\u006e\u007a\u003f\u0072\u006d\u0054\u004f\u0060\u004f\u0050\u006a\u0051\u0058\u006d\u0053\u0050\u006a\u0051\u0039\u0039\u0073\u0043\u004c\u004b\u0068\u007c\u002b\u0022\u0076\u006a\u0026\u0032\u0034\u0035\u0037\u0069\u0023\u002a\u006a\u0051\u0042\u0023\u006a\u003a\u0026\u0079\u004c\u0026\u004c\u005f\u0038\u004e\u0044\u005d\u0058\u0040\u004b\u0036\u0041\u006a\u0040\u006b\u0037\u0071\u0076\u0025\u004f\u0060\u004f\u0050\u006a\u0051\u0058\u006d\u0053\u0050\u006a\u0051\u0039\u0039\u0073\u0043\u004c\u004b\u0068\u007c\u002b\u0022\u0076\u006a\u0026\u0032\u0034\u0035\u0054\u0024\u0073\u007b\u0050\u002a\u003d\u0078\u0055\u0024\u005a\u003e\u003e\u006e\u0059\u0038\u0037\u0055\u004c\u0043\u0021\u002a\u006b\u0054\u0025\u003f\u0056\u0042\u0028\u0071\u0025\u0040\u003c\u0031\u006b\u002b\u0068\u0029\u0044\u002b\u004a\u004c\u003f\u0069\u005f\u003e\u0047\u0024\u0035\u0035\u007c\u0045\u0021\u0038\u006d\u0022\u004a\u0043\u0079\u003c\u0039\u0023\u0023\u0068\u0048\u0029\u0023\u002a\u006a\u0051\u0042\u0023\u006a\u003a\u0026\u0079\u004c\u0026\u004c\u005f\u0038\u004e\u0044\u005d\u0058\u0040\u005e\u002b\u0035\u0032\u006e\u007a\u0065\u0040\u0076\u0025\u004f\u0060\u004f\u0050\u006a\u0051\u0058\u006d\u0053\u0050\u0034\u0062\u002b\u007b\u005f\u0058\u0074\u003e\u006b\u0026\u0025\u0024\u005b\u0054\u0037\u0033\u0072\u0028\u005b\u006f\u006b\u002b\u0068\u0029\u0044\u002b\u0075\u005a\u0037\u004c\u003b\u007b\u0021\u006f\u0070\u0070\u0057\u002b\u0068\u0029\u0044\u002b\u0075\u005a\u0052\u0022\u0074\u0042\u0023\u002e\u0034\u0076\u0053\u002c\u0078\u0029\u004e\u002c\u0078\u0033\u0052\u0069\u0051\u0072\u0038\u005a\u0054\u0069\u0044\u002b\u004a\u004c\u004a\u004e\u007d\u0077\u0028\u006f\u007b\u0068\u0036\u0058\u0040\u006b\u0059\u002e\u0042\u0054\u004f\u0030\u0040\u0045\u0056\u006e\u007c\u006c\u0077\u006c\u0073\u002a\u005f\u003e\u0051\u003f\u0032\u0041\u006d\u0048\u0062\u0038\u006c\u0059\u006b\u002f\u0044\u0041\u003e\u002b\u0051\u0066\u004a\u0036\u0051\u0048\u006a\u0051\u003c\u0053\u002b\u0036\u0032\u002a\u0025\u007c\u004d\u0044\u0062\u0070\u006c\u0033\u004d\u0040\u0030\u005b\u0054\u007b\u002f\u002a\u0044\u002b\u0046\u0078\u0028\u0034\u0025\u0045\u0034\u0035\u003f\u0036\u0056\u0045\u0032\u002a\u0026\u0030\u0056\u0066\u004a\u0036\u003e\u0048\u0075\u0062\u0070\u0070\u0070\u005e\u0068\u0029\u005f\u003e\u003d\u0024\u005d\u0045\u005a\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u0040\u007c\u0067\u0022\u005f\u0070\u005f\u0033\u003f\u0053\u0038\u0076\u005e\u0036\u004f\u005d\u0071\u0048\u0040\u003f\u007c\u007d\u006b\u0045\u0056\u006e\u006a\u0054\u0061\u004c\u0039\u0029\u0048\u002e\u0042\u0054\u0072\u002c\u004e\u0071\u005e\u0040\u0033\u004e\u003c\u002f\u0058\u007a\u0029\u002b\u006f\u0063\u0044\u0054\u005a\u002f\u0068\u0035\u0070\u0068\u0056\u0045\u003c\u004f\u0029\u002b\u0065\u0022\u007d\u0071\u0032\u0045\u0031\u006f\u006a\u0054\u002c\u007b\u003c\u007a\u0029\u002b\u0054\u0024\u0064\u0064\u0047\u0037\u0041\u0040\u003c\u0031\u006b\u002b\u0068\u0029\u0044\u002b\u0075\u005a\u005b\u003d\u007a\u0032\u0053\u0051\u0079\u0057\u0054\u006c\u0062\u006b\u0039\u0023\u006f\u0063\u0066\u0071\u007a\u0056\u003b\u0033\u0073\u0059\u0033\u005a\u0039\u0029\u002c\u003d\u003b\u0024\u0072\u0044\u0039\u0028\u007c\u006f\u0062\u0053\u0050\u004e\u0039\u002a\u0044\u002b\u0065\u005a\u004d\u0043\u0059\u0048\u006a\u0051\u003c\u0053\u002b\u0036\u0032\u002a\u0025\u007c\u004d\u0044\u0062\u0070\u006c\u0033\u004d\u0040\u0030\u005b\u0054\u007b\u002f\u002a\u0044\u002b\u0046\u0078\u0028\u0034\u0025\u0045\u0034\u0035\u003f\u0036\u0056\u0045\u0032\u002a\u0026\u0030\u0056\u0066\u004a\u0036\u003e\u0048\u0075\u0062\u0070\u0070\u0070\u005e\u0068\u0029\u005f\u003e\u003d\u0024\u005d\u0045\u005a\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u0040\u007c\u0067\u0022\u005f\u0070\u005f\u0033\u003f\u0053\u0038\u0076\u005e\u0036\u004f\u005d\u0071\u0048\u0040\u003f\u007c\u007d\u006b\u0045\u0056\u006e\u006a\u0054\u0059\u0054\u0039\u0029\u0048\u002e\u0042\u0054\u005d\u0029\u0037\u0048\u0022\u0044\u004b\u006d\u0021\u0062\u004d\u0040\u0060\u0054\u0046\u005d\u005b\u0072\u005f\u0048\u0067\u0022\u004a\u0036\u006d\u004a\u0029\u0056\u005f\u0054\u002c\u005e\u0065\u0076\u0022\u0026\u0058\u0022\u0038\u0064\u003e\u0023\u0044\u0044\u0060\u0054\u002c\u005e\u0022\u0031\u0039\u0023\u0061\u0068\u0076\u0066\u0035\u005d\u002a\u0051\u0058\u006d\u0053\u0050\u0033\u007c\u0045\u003a\u0066\u0034\u0044\u0048\u002b\u0025\u0076\u0024\u0028\u0064\u0047\u0037\u0066\u003c\u004f\u0040\u0028\u006c\u0067\u0046\u0058\u003d\u004c\u0054\u007e\u004c\u004e\u0032\u0048\u004b\u0057\u0031\u007b\u003a\u006c\u0076\u0039\u0023\u002b\u0023\u0022\u0069\u0048\u002e\u0042\u0054\u003c\u0065\u005f\u0048\u006a\u0051\u003c\u0053\u002b\u0036\u0032\u002a\u0025\u007c\u004d\u0044\u0062\u0070\u006c\u0033\u004d\u0040\u0030\u005b\u0054\u007b\u002f\u002a\u0044\u002b\u0046\u0078\u0028\u0034\u0025\u0045\u0034\u0035\u003f\u0036\u0056\u0045\u0032\u002a\u0026\u0030\u0056\u0066\u004a\u0036\u002b\u0032\u0068\u0036\u0021\u0048\u0039\u004d\u0058\u006d\u0053\u0050\u0071\u0066\u0072\u0059\u0035\u0068\u002c\u0029\u0062\u0048\u0030\u003f\u0043\u006a\u0044\u005d\u006e\u0026\u003b\u0076\u0035\u0043\u0028\u0079\u0074\u0046\u006c\u0066\u0022\u0069\u002c\u003d\u003b\u0024\u0072\u0044\u0039\u0028\u007c\u006f\u0062\u0053\u0050\u004e\u0025\u002a\u0044\u002b\u0065\u005a\u0039\u002a\u0062\u006b\u0029\u0056\u005f\u0054\u0046\u005d\u0066\u0055\u0029\u002b\u0050\u0054\u005e\u0043\u0040\u0045\u0038\u006f\u007d\u0053\u0050\u004e\u0053\u004f\u0071\u0072\u0050\u0054\u0038\u0051\u005f\u0033\u0067\u006b\u006b\u0040\u003c\u002f\u002f\u0057\u0059\u0050\u0050\u0054\u0069\u005d\u0032\u0062\u004d\u0040\u003f\u0054\u0071\u0032\u0044\u0021\u0044\u002b\u004a\u004c\u004c\u0031\u0048\u0056\u0064\u0057\u005d\u0050\u007d\u0068\u002b\u0047\u0053\u005f\u007e\u005a\u004d\u0043\u006c\u0033\u0031\u006f\u0062\u0053\u0028\u0079\u0067\u007c\u003e\u002b\u003a\u0078\u0059\u0070\u0036\u0033\u0073\u0028\u0055\u0040\u0028\u006c\u0021\u002a\u0044\u0023\u004a\u004c\u0064\u0064\u002b\u002a\u006a\u003f\u003f\u0054\u0046\u005d\u0066\u0055\u0029\u002b\u0050\u0054\u005e\u0043\u0040\u0045\u0038\u006f\u007d\u0053\u0050\u004e\u0053\u004f\u0071\u0072\u0050\u0054\u0038\u0051\u005f\u0033\u0067\u006b\u006b\u0040\u003c\u002f\u002f\u0057\u0059\u0050\u0050\u0054\u0069\u005d\u0032\u0062\u004d\u0040\u003f\u0054\u0071\u0032\u0044\u0021\u0044\u002b\u004a\u004c\u004c\u0031\u0048\u0056\u0064\u0057\u005d\u0050\u007d\u0068\u002b\u0047\u0053\u005f\u007e\u005a\u004d\u0043\u006c\u0033\u0031\u006f\u0062\u0053\u0028\u0079\u0067\u007c\u003e\u002b\u003a\u0078\u0059\u0070\u0036\u0033\u0073\u0028\u0055\u0040\u0028\u006c\u0021\u002a\u0063\u0023\u0050\u0054\u0031\u007a\u0044\u005d\u0030\u0078\u0021\u003e\u0054\u007b\u002f\u002a\u0046\u0054\u0065\u005a\u0078\u0029\u006d\u0042\u006e\u0026\u004f\u0040\u0066\u0034\u003f\u0055\u0030\u0078\u0058\u0039\u007b\u002c\u006d\u0042\u005a\u003c\u0038\u0076\u0025\u0039\u0043\u003c\u0039\u0023\u0023\u0068\u006a\u0029\u006d\u0042\u0040\u007c\u006e\u0053\u0050\u004e\u0045\u002a\u007b\u0057\u006a\u0042\u0054\u0069\u0044\u002b\u004a\u004c\u0035\u0042\u0035\u0071\u0070\u0051\u0074\u004b\u0073\u0065\u0077\u003d\u0025\u0078\u0062\u0040\u007d\u006a\u0033\u0023\u0037\u0033\u0070\u0070\u0070\u005e\u0068\u0029\u005f\u003e\u003d\u0024\u005d\u0045\u005a\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u006d\u0040\u002f\u005f\u003e\u0045\u0055\u0033\u003f\u0053\u0038\u0076\u005e\u0036\u004f\u005d\u0071\u0048\u0040\u003f\u007c\u007d\u006b\u0045\u0056\u006e\u006a\u0054\u004f\u0065\u002b\u002a\u0044\u002b\u0065\u005a\u002b\u004e\u003e\u0048\u0022\u0044\u004b\u006d\u0021\u0062\u004d\u0040\u0060\u0054\u0046\u005d\u005b\u0072\u005f\u0048\u0067\u0022\u004a\u0036\u005f\u0048\u0041\u0040\u0043\u0029\u0077\u006c\u007d\u007e\u006a\u0048\u007e\u005a\u0058\u0037\u0051\u0048\u006a\u0051\u0047\u0047\u003c\u002f\u0047\u0037\u0040\u007c\u0038\u005a\u0054\u0069\u0044\u002b\u004a\u004c\u004a\u004e\u007d\u0077\u0028\u006f\u007b\u0068\u0036\u0058\u0040\u006b\u0059\u002e\u0042\u0054\u0077\u003f\u004d\u0077\u0047\u0053\u007c\u006c\u0077\u006c\u0073\u002a\u005f\u003e\u0051\u003f\u0032\u0041\u006d\u0048\u0062\u0038\u006c\u0059\u006b\u002f\u004f\u005e\u005e\u0040\u004a\u004c\u0064\u0064\u003e\u0023\u005a\u0024\u004b\u006d\u0021\u0062\u004d\u0040\u0060\u0054\u0046\u005d\u005b\u0072\u005f\u0048\u0067\u0022\u004a\u0036\u005f\u0048\u0041\u0040\u0043\u0029\u0077\u006c\u007d\u007e\u006a\u0048\u007e\u005a\u0058\u0037\u0051\u0048\u006a\u0051\u0047\u0047\u003c\u002f\u0047\u0037\u0040\u007c\u0038\u005a\u0054\u0069\u0044\u002b\u004a\u004c\u004a\u004e\u007d\u0077\u0028\u006f\u007b\u0068\u0036\u0058\u0040\u006b\u0059\u002e\u0042\u0054\u0077\u003f\u004d\u0077\u0047\u0053\u007c\u006c\u0077\u006c\u0073\u002a\u005f\u003e\u0051\u003f\u0032\u0041\u006d\u0048\u0062\u0038\u006c\u0059\u006b\u002f\u0070\u0032\u005e\u0040\u004a\u004c\u0064\u0064\u003e\u0023\u006d\u0022\u0060\u0054\u0046\u005d\u0066\u0055\u0029\u002b\u0050\u0054\u005e\u0043\u0040\u0045\u0038\u006f\u007d\u0053\u002b\u0036\u007e\u0037\u0029\u002b\u0065\u0022\u007d\u0071\u0032\u0045\u0031\u006f\u006a\u0054\u0041\u002f\u0032\u002a\u0026\u0030\u0056\u0066\u004a\u0036\u005f\u0048\u0075\u0062\u0070\u0070\u0070\u005e\u0068\u0029\u005f\u003e\u003d\u0024\u005d\u0045\u005a\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u006d\u0040\u002f\u005f\u003e\u0045\u0055\u0033\u003f\u0053\u0038\u0076\u005e\u0036\u004f\u005d\u0071\u0048\u0040\u003f\u007c\u007d\u006b\u0045\u0056\u006e\u006a\u0054\u0047\u0070\u002b\u002a\u0044\u002b\u0065\u005a\u0039\u002a\u0040\u004a\u0029\u0056\u005f\u0054\u0046\u005d\u0066\u0055\u0029\u002b\u0050\u0054\u005e\u0043\u0040\u0045\u0038\u006f\u007d\u0053\u002b\u0036\u007e\u0037\u0029\u002b\u0065\u0022\u007d\u0071\u0032\u0045\u0031\u006f\u006a\u0054\u0041\u002f\u0032\u002a\u0026\u0030\u0056\u0066\u004a\u0036\u005f\u0048\u0075\u0062\u0070\u0070\u0070\u005e\u0068\u0029\u005f\u003e\u003d\u0024\u005d\u0045\u005a\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u006d\u0040\u002f\u005f\u003e\u0045\u0055\u0033\u003f\u0053\u0038\u0076\u005e\u0036\u004f\u005d\u0071\u0048\u0040\u003f\u007c\u007d\u006b\u0045\u0056\u006e\u006a\u0054\u0066\u0065\u002b\u002a\u0044\u002b\u0065\u005a\u002b\u004e\u007a\u0071\u0041\u0040\u0033\u004e\u003c\u002f\u0058\u007a\u0029\u002b\u006f\u0063\u0044\u0054\u005a\u002f\u0068\u0035\u006d\u0054\u0053\u0032\u0039\u0029\u0077\u0046\u005e\u0044\u0072\u0030\u007a\u0056\u004d\u0040\u0030\u002b\u002b\u0036\u003e\u0037\u005d\u002e\u0042\u0054\u0025\u0036\u0021\u0048\u0039\u004d\u0058\u006d\u003c\u006b\u006d\u006f\u0061\u0063\u0074\u002f\u004c\u0021\u0044\u002b\u0075\u005a\u005f\u0071\u0044\u002f\u0043\u0057\u006d\u0032\u004a\u0043\u007d\u0055\u0030\u0078\u003d\u007d\u0035\u0070\u0076\u0028\u0030\u0077\u006e\u0075\u003b\u002f\u0036\u0029\u0044\u002b\u004a\u004c\u0071\u0036\u005b\u002f\u0064\u006f\u003a\u006f\u0058\u005d\u003a\u004e\u0039\u0023\u003e\u003f\u0046\u0024\u003e\u006e\u0021\u004f\u005d\u0059\u0041\u0036\u0044\u0048\u002b\u0025\u0076\u0024\u0028\u0064\u003e\u0023\u006f\u0057\u0068\u007b\u0053\u0043\u0028\u0079\u0053\u0026\u0071\u0063\u0066\u0054\u0050\u0042\u0021\u0038\u004a\u003a\u0036\u0058\u003c\u0048\u0061\u0046\u0042\u0054\u0059\u003d\u004b\u0028\u0071\u0038\u0033\u006f\u002c\u0068\u004d\u007e\u0060\u0025\u0053\u005f\u003c\u0034\u007c\u0042\u002e\u006f\u0071\u0050\u003c\u007e\u006a\u002c\u002a\u0079\u0035\u002e\u0061\u004d\u0037\u0050\u003e\u0037\u0021\u0030\u003f\u0044\u0035\u0053\u006b\u0041\u0057\u004d\u0023\u0073\u0043\u0060\u0043\u0051\u0023\u0040\u004c\u003f\u0069\u005f\u003e\u0048\u003f\u005d\u0070\u004b\u0028\u0046\u0028\u0033\u004e\u0046\u006c\u0021\u002a\u005b\u0048\u0077\u005f\u0055\u007b\u0035\u0056\u0048\u004b\u0072\u0059\u0041\u0036\u0071\u0067\u007e\u005f\u002f\u005f\u006a\u0045\u0055\u0033\u004d\u0040\u0046\u0059\u0035\u0043\u004e\u0067\u002e\u006b\u0060\u0078\u0054\u0034\u0070\u0056\u006a\u0064\u0078\u0075\u0028\u006c\u0045\u006c\u005f\u003e\u0067\u0022\u007e\u006a\u002c\u002a\u0079\u0035\u002e\u0061\u0036\u0023\u0050\u003e\u0061\u0023\u003f\u0022\u0063\u0024\u0053\u006b\u0041\u0057\u004d\u0023\u0073\u0043\u0060\u0043\u0051\u0023\u0040\u004c\u003f\u0069\u005f\u003e\u0048\u003f\u005d\u0070\u004b\u0028\u0046\u0028\u0033\u004e\u0046\u006c\u0021\u002a\u005b\u0048\u0077\u005f\u0057\u0065\u004e\u0056\u003e\u004b\u003c\u0063\u0036\u0058\u003f\u002a\u0025\u007c\u0053\u005f\u0028\u003f\u006e\u0077\u0047\u0053\u006a\u0054\u0030\u0043\u0079\u003c\u007d\u0064\u0071\u0063\u0066\u0054\u0036\u006e\u006c\u006f\u0075\u007b\u004c\u0068\u0066\u007e\u0050\u002e\u0028\u0075\u003e\u0069\u0045\u005e\u0036\u0044\u007b\u0071\u002b\u002a\u0052\u0038\u0023\u0064\u0026\u0033\u0065\u0032\u0050\u002e\u0055\u0024\u007c\u0031\u0021\u0048\u005d\u0064\u005e\u0023\u006a\u003a\u004f\u0049\u0024\u006d\u002c\u005e\u0024\u0067\u002c\u003d\u0072\u0063\u004f\u0060\u006b\u006b\u0063\u0037\u0036\u0022\u0061\u002f\u004c\u0021\u0022\u0022\u0074\u003f\u0076\u0071\u007c\u0045\u003b\u0035\u007a\u007a\u0053\u0068\u002c\u0029\u002a\u0046\u005b\u0078\u0056\u0035\u003b\u005e\u0043\u003b\u0028\u003c\u0046\u005e\u0021\u0053\u0037\u0048\u006f\u0034\u0031\u0062\u0026\u0032\u0053\u0051\u003b\u0055\u0072\u0034\u0051\u004e\u006c\u0070\u0059\u004c\u007c\u007b\u0023\u006a\u0059\u006e\u004b\u006c\u006b\u002b\u0071\u0048\u0044\u006b\u007b\u0024\u0023\u002b\u0039\u0028\u007c\u006f\u0045\u003a\u0043\u005d\u0033\u0029\u0026\u004a\u0040\u004c\u0041\u0034\u005f\u003c\u006f\u0024\u0049\u004c\u0048\u006a\u0074\u0058\u0054\u0022\u0048\u003d\u0041\u0034\u005f\u003c\u0047\u004a\u0023\u002b\u0053\u007b\u0046\u0028\u0023\u0075\u0057\u003a\u003e\u0069\u0067\u003e\u003c\u0075\u0046\u0069\u0063\u0075\u002b\u0039\u0022\u006c\u0057\u0041\u0070\u0051\u0062\u0030\u003a\u004e\u006b\u006f\u003d\u0078\u004a\u0068\u003b\u007d\u0077\u006e\u004d\u0033\u0074\u0065\u0070\u005e\u0042\u007e\u003c\u006f\u0024\u0034\u003c\u007b\u0026\u0071\u003e\u0056\u0036\u0039\u0037\u004d\u0042\u007e\u0028\u006f\u0024\u0034\u003c\u007b\u0032\u004a\u003e\u0056\u0061\u0068\u0037\u004d\u0042\u007e\u0077\u0022\u0057\u0075\u0046\u0069\u0057\u0057\u002f\u0034\u0077\u0037\u0050\u005e\u0070\u0051\u0051\u0024\u0064\u0036\u0059\u0029\u0029\u0075\u0046\u0068\u0047\u0029\u005a\u0041\u0070\u0051\u0034\u006d\u0033\u0037\u0042\u005d\u0021\u0024\u0034\u002f\u005b\u003c\u005f\u0072\u0051\u0025\u0076\u0029\u007c\u0042\u0047\u004a\u004f\u0024\u0034\u002f\u005b\u003c\u0071\u0050\u0051\u0025\u0048\u0029\u007c\u0042\u0047\u004a\u0060\u0039\u007c\u0036\u0059\u0029\u003c\u0057\u005e\u003a\u0059\u002a\u0057\u0041\u0070\u0051\u002f\u0054\u0064\u0036\u0059\u0029\u0048\u0075\u002b\u0039\u0050\u004b\u0052\u0041\u0070\u0051\u007a\u0068\u0028\u007b\u006b\u006f\u002e\u0070\u002c\u0068\u0055\u007d\u0026\u0071\u0025\u004d\u0072\u0058\u006b\u002b\u003e\u007b\u002e\u006b\u0049\u003f\u006a\u0071\u003c\u006a\u003c\u0051\u004d\u006f\u002a\u0039\u0041\u0050\u003d\u005d\u005e\u0044\u0067\u0030\u0065\u0042\u006a\u0055\u0034\u006d\u0059\u0023\u0050\u006b\u0043\u0029\u0077\u005d\u004d\u0053\u0046\u003d\u0025\u007d\u006d\u0070\u0032\u0062\u0065\u0051\u0074\u0072\u0070\u005e\u0068\u0029\u0046\u0054\u0023\u0063\u005f\u0071\u0060\u0028\u0057\u006f\u0072\u0050\u004b\u002f\u007c\u0058\u0034\u0026\u0044\u004c\u0075\u0043\u0023\u006a\u0070\u0037\u0053\u0063\u0025\u007b\u0064\u004f\u0046\u003d\u0025\u007d\u0052\u0066\u0058\u0045\u0056\u006e\u0075\u0023\u0058\u005e\u004d\u0052\u0068\u007c\u004d\u0044\u0066\u0054\u0060\u0028\u002e\u0056\u004b\u0059\u0060\u006c\u0030\u0072\u0062\u0025\u005a\u0063\u005f\u0071\u0060\u0028\u0051\u0038\u003b\u0040\u0077\u0068\u003c\u003c\u004f\u002b\u0035\u0021\u006e\u0060\u004f\u0050\u006d\u0074\u0034\u006d\u0059\u0023\u0050\u006b\u0043\u0029\u0032\u006c\u0023\u004e\u0022\u0026\u0058\u0030\u006b\u004b\u006a\u006e\u006f\u006f\u0072\u0040\u0077\u0068\u0061\u0052\u0055\u0072\u0059\u004c\u007c\u007b\u0077\u0028\u004d\u0031\u0069\u007c\u0046\u006c\u0068\u004e\u0061\u0054\u0060\u004c\u0073\u005b\u004f\u0050\u006a\u0051\u0059\u0036\u0072\u0034\u0034\u0072\u002c\u005f\u007c\u0024\u0058\u0024\u0048\u0056\u0021\u006f\u0043\u0053\u0053\u0068\u006f\u0070\u0045\u0023\u0040\u004c\u0052\u006f\u005f\u0030\u003f\u004d\u0061\u0062\u0072\u0034\u0077\u0048\u0062\u0025\u0025\u007d\u003a\u002b\u0070\u0056\u0038\u006f\u0034\u0055\u0072\u0034\u0051\u004e\u002a\u0078\u002e\u0078\u0030\u003d\u007a\u0032\u0056\u006e\u004d\u003a\u007b\u0058\u0033\u0043\u005f\u0048\u0060\u004c\u0033\u0070\u003a\u0056\u0065\u0051\u0074\u0072\u0070\u005e\u0026\u006e\u0021\u002e\u0077\u005f\u0045\u002b\u003f\u005e\u0074\u007c\u007a\u0057\u0077\u006c\u006c\u003c\u0066\u0048\u005b\u005b\u004a\u0046\u0058\u0045\u0037\u0063\u0034\u006d\u0053\u0050\u0033\u0038\u0060\u0059\u0030\u0058\u0030\u0043\u0070\u006b\u006b\u007d\u0056\u003d\u004e\u0056\u0058\u0072\u007a\u0057\u0077\u006c\u006c\u003c\u0022\u004a\u002b\u0030\u0055\u003f\u0036\u006e\u0063\u0056\u0076\u0055\u0044\u003a\u0074\u0037\u0064\u0048\u007b\u0024\u0061\u005e\u005b\u002f\u0064\u006f\u003a\u006f\u0052\u004e\u003b\u0058\u0030\u0026\u005a\u0024\u0076\u0042\u007a\u0032\u005f\u0060\u0021\u0050\u004b\u002f\u0056\u0029\u0053\u006e\u0031\u003f\u006d\u0041\u0046\u0028\u0057\u007b\u0068\u003a\u0035\u0034\u007b\u0037\u0043\u0046\u0025\u007d\u0062\u003d\u0036\u006e\u005b\u004b\u006c\u0040\u0048\u0039\u0079\u0076\u004b\u0078\u0068\u007d\u002e\u0024\u0033\u0077\u0052\u0060\u006b\u006c\u006b\u002b\u0068\u0029\u005b\u0048\u0077\u005f\u0055\u0032\u0042\u0056\u0075\u006f\u0041\u0037\u0047\u0079\u0037\u003c\u0071\u0075\u004a\u0078\u007e\u0030\u0055\u0023\u006f\u0057\u0068\u007b\u0053\u0043\u0028\u0079\u0053\u0026\u0071\u0063\u0066\u0054\u0074\u0023\u007e\u0063\u0062\u003c\u0077\u002b\u003e\u007b\u002e\u006b\u0049\u003f\u006a\u0071\u003c\u006a\u003c\u0051\u0061\u0057\u0054\u006c\u0056\u0034\u002b\u007a\u0073\u0070\u0026\u0032\u0035\u0028\u0055\u0040\u0028\u006c\u005a\u0029\u0026\u004a\u0040\u004c\u002e\u0023\u003a\u0056\u0031\u006f\u004e\u005b\u002e\u006c\u006c\u0067\u0050\u0075\u003c\u0034\u0054\u0069\u0026\u0030\u0040\u004c\u006b\u0032\u003c\u006a\u0025\u006f\u005d\u0050\u005d\u0058\u0038\u0048\u006c\u0070\u0059\u004c\u0075\u0046\u0059\u0033\u0056\u0038\u0061\u0030\u0025\u005a\u0073\u0048\u0071\u002e\u0051\u003f\u0033\u003d\u0029\u004f\u0052\u0057\u0053\u0057\u0036\u0058\u002e\u003c\u0022\u004a\u0034\u0021\u0044\u0077\u006f\u006d\u004a\u004c\u0071\u0035\u0034\u0028\u006f